            type="email"
            autoComplete="email"
            placeholder="ada@company.com"
            isRequired
          />
          <div className="grid gap-3">
            <PasswordField
              label="Password"
              name="password"
              autoComplete="new-password"
              description="Use 12 or more characters. Mix letters with numbers or symbols."
              value={password}
              onChange={setPassword}
              minLength={8}
              isRequired
            />
            <PasswordStrengthMeter password={password} />
          </div>
          <Select
            label="Team size"
            name="team"
            options={teamSizes}
            defaultValue="2-10"
          />
          <Checkbox
            name="terms"
            isRequired
            errorMessage="Accept the terms to create an account."
          >
            I agree to the terms of service
          </Checkbox>
          <Button type="submit" className="w-full">
            Create account
          </Button>
        </Form>
      </CardContent>
      <CardFooter className="justify-center gap-1 border-t border-border/70 pt-5 text-sm text-muted-foreground">
        Have an account?
        <Link href="#">Sign in</Link>
      </CardFooter>
    </Card>
  );
}
